 rect(g,'#b49a6a',x-4,top-8,w+8,8);rect(g,'#8a7048',x-4,top-2,w+8,3);for(let q=0;q<(w+8)/8;q++)rect(g,'rgba(0,0,0,.12)',x-4+q*8,top-8,1.2,6);
