 if(day>.2)each(o,300,8,(x,i,r)=>{const bx=x+Math.sin(t*.5+i)*50,by=44+r*90+Math.sin(t*1.3+i*2)*6,w=Math.sin(t*10+i*3)*4;g.lineWidth=2.6;g.strokeStyle='rgba(120,120,140,.5)';g.beginPath();g.moveTo(bx-9,by-w+1);g.quadraticCurveTo(bx-4,by-6-w+1,bx,by+1);g.quadraticCurveTo(bx+4,by-6+w+1,bx+9,by+w+1);g.stroke();g.lineWidth=2;g.strokeStyle='rgba(251,251,248,'+day+')';g.beginPath();g.moveTo(bx-9,by-w);g.quadraticCurveTo(bx-4,by-6-w,bx,by);g.quadraticCurveTo(bx+4,by-6+w,bx+9,by+w);g.stroke()});
